-- Generated by `python -m planner docs` from src/planner/schema.py — do not edit by hand.
-- SQLite dialect. Tables are created in dependency order; load with PRAGMA foreign_keys = ON.
PRAGMA foreign_keys = ON;

DROP TABLE IF EXISTS ground_truth;
DROP TABLE IF EXISTS shortage_event;
DROP TABLE IF EXISTS mitigation_option;
DROP TABLE IF EXISTS shortage_cause;
DROP TABLE IF EXISTS shortage;
DROP TABLE IF EXISTS projected_balance;
DROP TABLE IF EXISTS planned_order;
DROP TABLE IF EXISTS exception;
DROP TABLE IF EXISTS production_plan;
DROP TABLE IF EXISTS inventory;
DROP TABLE IF EXISTS inventory_txn;
DROP TABLE IF EXISTS purchase_order_event;
DROP TABLE IF EXISTS purchase_order;
DROP TABLE IF EXISTS forecast_demand;
DROP TABLE IF EXISTS production_capacity;
DROP TABLE IF EXISTS supplier_capacity;
DROP TABLE IF EXISTS lead_time;
DROP TABLE IF EXISTS bom;
DROP TABLE IF EXISTS sku_substitute;
DROP TABLE IF EXISTS supplier_sku;
DROP TABLE IF EXISTS sku_location;
DROP TABLE IF EXISTS supplier;
DROP TABLE IF EXISTS sku;
DROP TABLE IF EXISTS location;

-- Plants, distribution centres and stores.
CREATE TABLE location (
    location_id TEXT NOT NULL,
    location_name TEXT NOT NULL,
    location_type TEXT NOT NULL CHECK (location_type IN ('PLANT', 'DC', 'STORE')),
    city TEXT NOT NULL,
    region TEXT NOT NULL CHECK (region IN ('NORTH', 'SOUTH', 'EAST', 'WEST', 'CENTRAL')),
    is_active INTEGER NOT NULL CHECK (is_active IN (1, 0)),
    effective_from TEXT NOT NULL,
    PRIMARY KEY (location_id)
);

-- Stock-keeping units: finished goods and purchased components.
CREATE TABLE sku (
    sku_id TEXT NOT NULL,
    sku_name TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('BEVERAGES', 'SNACKS', 'DAIRY', 'STAPLES', 'PERSONAL_CARE', 'HOME_CARE', 'BABY_CARE', 'HOUSEHOLD_ELECTRICALS')),
    sku_type TEXT NOT NULL CHECK (sku_type IN ('FINISHED', 'COMPONENT')),
    sourcing_type TEXT NOT NULL CHECK (sourcing_type IN ('BUY', 'MAKE')),
    base_uom TEXT NOT NULL CHECK (base_uom IN ('EA')),
    case_pack_qty INTEGER NOT NULL CHECK (case_pack_qty IN (1, 6, 12, 24)),
    unit_cost_inr REAL NOT NULL CHECK (unit_cost_inr > 0),
    unit_price_inr REAL NOT NULL CHECK (unit_price_inr > 0),
    abc_class TEXT NOT NULL CHECK (abc_class IN ('A', 'B', 'C')),
    criticality TEXT NOT NULL CHECK (criticality IN ('HIGH', 'MEDIUM', 'LOW')),
    lifecycle_state TEXT NOT NULL CHECK (lifecycle_state IN ('NEW', 'ACTIVE', 'PHASE_OUT')),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    safety_stock_weeks INTEGER NOT NULL CHECK (safety_stock_weeks >= 0 AND safety_stock_weeks <= 6),
    PRIMARY KEY (sku_id)
);

-- Vendors that supply BUY SKUs. Constraint is not stored; it emerges from capacity.
CREATE TABLE supplier (
    supplier_id TEXT NOT NULL,
    supplier_name TEXT NOT NULL,
    home_region TEXT NOT NULL CHECK (home_region IN ('NORTH', 'SOUTH', 'EAST', 'WEST', 'CENTRAL')),
    status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'ON_HOLD', 'INACTIVE')),
    on_time_rate REAL NOT NULL CHECK (on_time_rate >= 0 AND on_time_rate <= 1),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    PRIMARY KEY (supplier_id)
);

-- Assortment bridge (SKU N:M Location): which SKU is stocked where, with safety stock.
CREATE TABLE sku_location (
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    safety_stock_qty INTEGER NOT NULL CHECK (safety_stock_qty >= 0),
    is_active INTEGER NOT NULL CHECK (is_active IN (1, 0)),
    effective_from TEXT NOT NULL,
    PRIMARY KEY (sku_id, location_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id)
);

-- Sourcing bridge (Supplier N:M SKU) with commercial terms.
CREATE TABLE supplier_sku (
    supplier_sku_id TEXT NOT NULL,
    supplier_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    is_primary INTEGER NOT NULL CHECK (is_primary IN (1, 0)),
    approval_status TEXT NOT NULL CHECK (approval_status IN ('APPROVED', 'PENDING', 'REJECTED')),
    unit_cost_inr REAL NOT NULL CHECK (unit_cost_inr > 0),
    purchase_uom TEXT NOT NULL CHECK (purchase_uom IN ('EA', 'CASE')),
    uom_conversion INTEGER NOT NULL CHECK (uom_conversion >= 1),
    moq INTEGER NOT NULL CHECK (moq >= 1),
    order_multiple INTEGER NOT NULL CHECK (order_multiple >= 1),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    PRIMARY KEY (supplier_sku_id),
    UNIQUE (supplier_id, sku_id, effective_from),
    FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id)
);

-- Substitution bridge (SKU N:M SKU): which SKU may replace another.
CREATE TABLE sku_substitute (
    substitute_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    substitute_sku_id TEXT NOT NULL,
    approval_status TEXT NOT NULL CHECK (approval_status IN ('APPROVED', 'PENDING', 'REJECTED')),
    substitution_ratio REAL NOT NULL CHECK (substitution_ratio > 0 AND substitution_ratio <= 2),
    price_delta_pct REAL NOT NULL CHECK (price_delta_pct >= -50 AND price_delta_pct <= 50),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    PRIMARY KEY (substitute_id),
    UNIQUE (sku_id, substitute_sku_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (substitute_sku_id) REFERENCES sku (sku_id)
);

-- Bill of materials bridge (MAKE SKU N:M COMPONENT SKU).
CREATE TABLE bom (
    bom_id TEXT NOT NULL,
    parent_sku_id TEXT NOT NULL,
    component_sku_id TEXT NOT NULL,
    qty_per INTEGER NOT NULL CHECK (qty_per >= 1),
    uom TEXT NOT NULL CHECK (uom IN ('EA')),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    PRIMARY KEY (bom_id),
    UNIQUE (parent_sku_id, component_sku_id, effective_from),
    FOREIGN KEY (parent_sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (component_sku_id) REFERENCES sku (sku_id)
);

-- Supplier-to-region transport lanes, versioned by effective date.
CREATE TABLE lead_time (
    lead_time_id TEXT NOT NULL,
    supplier_id TEXT NOT NULL,
    dest_region TEXT NOT NULL CHECK (dest_region IN ('NORTH', 'SOUTH', 'EAST', 'WEST', 'CENTRAL')),
    transport_mode TEXT NOT NULL CHECK (transport_mode IN ('ROAD', 'RAIL', 'SEA', 'AIR')),
    is_expedite_lane INTEGER NOT NULL CHECK (is_expedite_lane IN (1, 0)),
    production_days INTEGER NOT NULL CHECK (production_days >= 0),
    transit_days INTEGER NOT NULL CHECK (transit_days >= 0),
    total_lead_weeks INTEGER NOT NULL CHECK (total_lead_weeks >= 1),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    PRIMARY KEY (lead_time_id),
    UNIQUE (supplier_id, dest_region, is_expedite_lane, effective_from),
    FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id)
);

-- Quantity a supplier can deliver per receipt week (all SKUs combined).
CREATE TABLE supplier_capacity (
    capacity_id TEXT NOT NULL,
    supplier_id TEXT NOT NULL,
    week TEXT NOT NULL,
    capacity_qty_ea INTEGER NOT NULL CHECK (capacity_qty_ea >= 0),
    PRIMARY KEY (capacity_id),
    UNIQUE (supplier_id, week),
    FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id)
);

-- Plant production capacity per week (1 EA of any MAKE SKU = 1 capacity unit).
CREATE TABLE production_capacity (
    plant_location_id TEXT NOT NULL,
    week TEXT NOT NULL,
    capacity_qty_ea INTEGER NOT NULL CHECK (capacity_qty_ea >= 0),
    PRIMARY KEY (plant_location_id, week),
    FOREIGN KEY (plant_location_id) REFERENCES location (location_id)
);

-- Weekly forecast demand per FINISHED SKU-location.
CREATE TABLE forecast_demand (
    demand_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    week TEXT NOT NULL,
    week_start_date TEXT NOT NULL,
    baseline_qty_ea INTEGER NOT NULL CHECK (baseline_qty_ea >= 0),
    forecast_qty_ea INTEGER NOT NULL CHECK (forecast_qty_ea >= 0),
    demand_driver TEXT NOT NULL CHECK (demand_driver IN ('BASELINE', 'SEASONAL_PEAK', 'PROMO')),
    PRIMARY KEY (demand_id),
    UNIQUE (sku_id, location_id, week),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id),
    FOREIGN KEY (sku_id, location_id) REFERENCES sku_location (sku_id, location_id)
);

-- Inbound purchase orders (firm supply).
CREATE TABLE purchase_order (
    po_id TEXT NOT NULL,
    supplier_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    ship_to_location_id TEXT NOT NULL,
    supplier_sku_id TEXT NOT NULL,
    lead_time_id TEXT NOT NULL,
    order_date TEXT NOT NULL,
    order_qty INTEGER NOT NULL CHECK (order_qty > 0),
    order_uom TEXT NOT NULL CHECK (order_uom IN ('EA', 'CASE')),
    uom_conversion INTEGER NOT NULL CHECK (uom_conversion >= 1),
    qty_base_ea INTEGER NOT NULL CHECK (qty_base_ea >= 0),
    expected_receipt_week TEXT NOT NULL,
    delay_weeks INTEGER NOT NULL CHECK (delay_weeks >= 0 AND delay_weeks <= 6),
    revised_receipt_week TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('CREATED', 'CONFIRMED', 'SHIPPED', 'IN_TRANSIT', 'DELAYED', 'RECEIVED', 'CANCELLED')),
    created_by_role TEXT NOT NULL CHECK (created_by_role IN ('PLANNER')),
    PRIMARY KEY (po_id),
    FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (ship_to_location_id) REFERENCES location (location_id),
    FOREIGN KEY (supplier_sku_id) REFERENCES supplier_sku (supplier_sku_id),
    FOREIGN KEY (lead_time_id) REFERENCES lead_time (lead_time_id),
    FOREIGN KEY (sku_id, ship_to_location_id) REFERENCES sku_location (sku_id, location_id)
);

-- Append-only PO status history.
CREATE TABLE purchase_order_event (
    event_id TEXT NOT NULL,
    po_id TEXT NOT NULL,
    seq INTEGER NOT NULL CHECK (seq >= 1),
    from_status TEXT CHECK (from_status IN ('CREATED', 'CONFIRMED', 'SHIPPED', 'IN_TRANSIT', 'DELAYED', 'RECEIVED', 'CANCELLED')),
    to_status TEXT NOT NULL CHECK (to_status IN ('CREATED', 'CONFIRMED', 'SHIPPED', 'IN_TRANSIT', 'DELAYED', 'RECEIVED', 'CANCELLED')),
    event_ts TEXT NOT NULL,
    actor_role TEXT NOT NULL CHECK (actor_role IN ('PLANNER', 'SUPPLIER', 'CARRIER', 'WAREHOUSE_OPERATOR', 'LOGISTICS_ANALYST')),
    reason_code TEXT NOT NULL CHECK (reason_code IN ('PO_CREATED', 'SUPPLIER_CONFIRMED', 'DISPATCHED', 'HANDED_TO_CARRIER', 'TRANSPORT_DELAY', 'DELAY_CLEARED', 'GOODS_RECEIVED', 'DEMAND_CHANGE', 'SUPPLIER_REJECTED')),
    PRIMARY KEY (event_id),
    UNIQUE (po_id, seq),
    FOREIGN KEY (po_id) REFERENCES purchase_order (po_id)
);

-- Append-only inventory ledger from 2025-09-01 up to the as-of date.
CREATE TABLE inventory_txn (
    txn_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    txn_type TEXT NOT NULL CHECK (txn_type IN ('OPENING', 'RECEIPT', 'ISSUE', 'ADJUSTMENT')),
    qty_ea INTEGER NOT NULL,
    txn_date TEXT NOT NULL,
    ref_id TEXT,
    PRIMARY KEY (txn_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id),
    FOREIGN KEY (sku_id, location_id) REFERENCES sku_location (sku_id, location_id),
    FOREIGN KEY (ref_id) REFERENCES purchase_order (po_id)
);

-- Inventory snapshot at the as-of date: ON_HAND and IN_TRANSIT.
CREATE TABLE inventory (
    inventory_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    inventory_status TEXT NOT NULL CHECK (inventory_status IN ('ON_HAND', 'IN_TRANSIT')),
    qty_ea INTEGER NOT NULL CHECK (qty_ea >= 0),
    as_of_date TEXT NOT NULL,
    po_id TEXT,
    PRIMARY KEY (inventory_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id),
    FOREIGN KEY (sku_id, location_id) REFERENCES sku_location (sku_id, location_id),
    FOREIGN KEY (po_id) REFERENCES purchase_order (po_id)
);

-- Production of MAKE SKUs at plants. FIRM weeks are input; PLANNED weeks come from the planner.
CREATE TABLE production_plan (
    prod_plan_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    plant_location_id TEXT NOT NULL,
    week TEXT NOT NULL,
    planned_qty_ea INTEGER NOT NULL CHECK (planned_qty_ea >= 0),
    status TEXT NOT NULL CHECK (status IN ('FIRM', 'PLANNED')),
    capacity_used_ea INTEGER NOT NULL CHECK (capacity_used_ea >= 0),
    requested_qty_ea INTEGER NOT NULL CHECK (requested_qty_ea >= 0),
    capacity_cut_ea INTEGER NOT NULL CHECK (capacity_cut_ea >= 0),
    component_cut_ea INTEGER NOT NULL CHECK (component_cut_ea >= 0),
    PRIMARY KEY (prod_plan_id),
    UNIQUE (sku_id, plant_location_id, week),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (plant_location_id) REFERENCES location (location_id),
    FOREIGN KEY (sku_id, plant_location_id) REFERENCES sku_location (sku_id, location_id)
);

-- Quality-gate and policy exceptions with the action taken (the exception path).
CREATE TABLE exception (
    exception_id TEXT NOT NULL,
    issue_type TEXT NOT NULL CHECK (issue_type IN ('DUPLICATE_INBOUND', 'UNAPPROVED_SUBSTITUTE', 'SUPPLIER_CAPACITY_EXCEEDED', 'LEAD_TIME_IGNORED', 'UOM_MISMATCH')),
    entity TEXT NOT NULL CHECK (entity IN ('inventory', 'purchase_order', 'mitigation_option')),
    record_id TEXT NOT NULL,
    related_record_ids TEXT,
    detection_rule TEXT NOT NULL,
    action_taken TEXT NOT NULL CHECK (action_taken IN ('EXCLUDED', 'CORRECTED', 'CAPPED', 'FLAGGED')),
    severity TEXT NOT NULL CHECK (severity IN ('HIGH', 'MEDIUM', 'LOW')),
    detail TEXT,
    PRIMARY KEY (exception_id)
);

-- MRP planned purchase orders created by the planner.
CREATE TABLE planned_order (
    planned_order_id TEXT NOT NULL,
    supplier_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    supplier_sku_id TEXT NOT NULL,
    lead_time_id TEXT NOT NULL,
    capacity_id TEXT NOT NULL,
    release_week TEXT NOT NULL,
    receipt_week TEXT NOT NULL,
    order_qty INTEGER NOT NULL CHECK (order_qty >= 0),
    order_uom TEXT NOT NULL CHECK (order_uom IN ('EA', 'CASE')),
    qty_base_ea INTEGER NOT NULL CHECK (qty_base_ea >= 0),
    requested_qty_ea INTEGER NOT NULL CHECK (requested_qty_ea >= 0),
    capacity_cut_ea INTEGER NOT NULL CHECK (capacity_cut_ea >= 0),
    PRIMARY KEY (planned_order_id),
    FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id),
    FOREIGN KEY (supplier_sku_id) REFERENCES supplier_sku (supplier_sku_id),
    FOREIGN KEY (lead_time_id) REFERENCES lead_time (lead_time_id),
    FOREIGN KEY (capacity_id) REFERENCES supplier_capacity (capacity_id),
    FOREIGN KEY (sku_id, location_id) REFERENCES sku_location (sku_id, location_id)
);

-- Projected available balance (PAB) per SKU-location-week.
CREATE TABLE projected_balance (
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    week TEXT NOT NULL,
    opening_qty INTEGER NOT NULL,
    firm_receipts INTEGER NOT NULL CHECK (firm_receipts >= 0),
    planned_receipts INTEGER NOT NULL CHECK (planned_receipts >= 0),
    production_receipts INTEGER NOT NULL CHECK (production_receipts >= 0),
    demand_qty INTEGER NOT NULL CHECK (demand_qty >= 0),
    closing_qty INTEGER NOT NULL,
    safety_stock_qty INTEGER NOT NULL CHECK (safety_stock_qty >= 0),
    balance_status TEXT NOT NULL CHECK (balance_status IN ('OK', 'BELOW_SS', 'STOCKOUT')),
    PRIMARY KEY (sku_id, location_id, week),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id),
    FOREIGN KEY (sku_id, location_id) REFERENCES sku_location (sku_id, location_id)
);

-- Contiguous runs of weeks with PAB below safety stock for one SKU-location.
CREATE TABLE shortage (
    shortage_id TEXT NOT NULL,
    sku_id TEXT NOT NULL,
    location_id TEXT NOT NULL,
    start_week TEXT NOT NULL,
    end_week TEXT NOT NULL,
    peak_week TEXT NOT NULL,
    shortage_type TEXT NOT NULL CHECK (shortage_type IN ('STOCKOUT', 'BELOW_SAFETY_STOCK')),
    shortage_qty_ea INTEGER NOT NULL CHECK (shortage_qty_ea >= 0),
    below_ss_qty_ea INTEGER NOT NULL CHECK (below_ss_qty_ea >= 0),
    value_at_risk_inr REAL NOT NULL CHECK (value_at_risk_inr >= 0),
    primary_cause TEXT NOT NULL CHECK (primary_cause IN ('DEMAND_SPIKE', 'PO_DELAYED', 'SUPPLIER_CAPACITY', 'LEAD_TIME_FENCE', 'LOW_OPENING_STOCK', 'COMPONENT_SHORTAGE')),
    explanation TEXT NOT NULL,
    priority_score REAL NOT NULL CHECK (priority_score >= 0),
    priority_rank INTEGER NOT NULL CHECK (priority_rank >= 1),
    status TEXT NOT NULL CHECK (status IN ('OPEN', 'MITIGATION_PROPOSED', 'MITIGATION_SELECTED', 'ESCALATED', 'BACKORDER_ACCEPTED')),
    PRIMARY KEY (shortage_id),
    UNIQUE (sku_id, location_id, start_week),
    FOREIGN KEY (sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (location_id) REFERENCES location (location_id),
    FOREIGN KEY (sku_id, location_id) REFERENCES sku_location (sku_id, location_id)
);

-- Bridge (Shortage N:M evidence): each derived cause with its evidence record.
CREATE TABLE shortage_cause (
    shortage_id TEXT NOT NULL,
    cause_code TEXT NOT NULL CHECK (cause_code IN ('DEMAND_SPIKE', 'PO_DELAYED', 'SUPPLIER_CAPACITY', 'LEAD_TIME_FENCE', 'LOW_OPENING_STOCK', 'COMPONENT_SHORTAGE')),
    evidence_type TEXT NOT NULL CHECK (evidence_type IN ('forecast_demand', 'purchase_order', 'planned_order', 'supplier_capacity', 'lead_time', 'inventory', 'production_plan', 'bom')),
    evidence_id TEXT NOT NULL,
    contribution_qty_ea INTEGER NOT NULL CHECK (contribution_qty_ea >= 0),
    PRIMARY KEY (shortage_id, cause_code, evidence_id),
    FOREIGN KEY (shortage_id) REFERENCES shortage (shortage_id)
);

-- Candidate mitigations per shortage with cost/service trade-offs.
CREATE TABLE mitigation_option (
    mitigation_id TEXT NOT NULL,
    shortage_id TEXT NOT NULL,
    option_seq INTEGER NOT NULL CHECK (option_seq >= 1 AND option_seq <= 99),
    option_type TEXT NOT NULL CHECK (option_type IN ('EXPEDITE_PO', 'ALTERNATE_SUPPLIER', 'TRANSFER', 'SUBSTITUTE_SKU', 'INCREASE_PRODUCTION', 'BACKORDER')),
    source TEXT NOT NULL CHECK (source IN ('SYSTEM', 'MANUAL')),
    created_by_role TEXT NOT NULL CHECK (created_by_role IN ('SYSTEM', 'PLANNER')),
    ref_po_id TEXT,
    ref_supplier_id TEXT,
    ref_lead_time_id TEXT,
    ref_from_location_id TEXT,
    ref_substitute_id TEXT,
    ref_substitute_sku_id TEXT,
    ref_plant_location_id TEXT,
    qty_covered_ea INTEGER NOT NULL CHECK (qty_covered_ea >= 0),
    coverage_pct REAL NOT NULL CHECK (coverage_pct >= 0 AND coverage_pct <= 1),
    arrival_week TEXT,
    weeks_late INTEGER NOT NULL CHECK (weeks_late >= 0),
    incremental_cost_inr REAL NOT NULL CHECK (incremental_cost_inr >= 0),
    fill_rate_after REAL NOT NULL CHECK (fill_rate_after >= 0 AND fill_rate_after <= 1),
    score REAL NOT NULL,
    policy_status TEXT NOT NULL CHECK (policy_status IN ('COMPLIANT', 'VIOLATION')),
    policy_violation_reason TEXT,
    requires_approval INTEGER NOT NULL CHECK (requires_approval IN (1, 0)),
    is_recommended INTEGER NOT NULL CHECK (is_recommended IN (1, 0)),
    PRIMARY KEY (mitigation_id),
    UNIQUE (shortage_id, option_seq),
    FOREIGN KEY (shortage_id) REFERENCES shortage (shortage_id),
    FOREIGN KEY (ref_po_id) REFERENCES purchase_order (po_id),
    FOREIGN KEY (ref_supplier_id) REFERENCES supplier (supplier_id),
    FOREIGN KEY (ref_lead_time_id) REFERENCES lead_time (lead_time_id),
    FOREIGN KEY (ref_from_location_id) REFERENCES location (location_id),
    FOREIGN KEY (ref_substitute_id) REFERENCES sku_substitute (substitute_id),
    FOREIGN KEY (ref_substitute_sku_id) REFERENCES sku (sku_id),
    FOREIGN KEY (ref_plant_location_id) REFERENCES location (location_id)
);

-- Append-only shortage status history.
CREATE TABLE shortage_event (
    event_id TEXT NOT NULL,
    shortage_id TEXT NOT NULL,
    seq INTEGER NOT NULL CHECK (seq >= 1),
    from_status TEXT CHECK (from_status IN ('OPEN', 'MITIGATION_PROPOSED', 'MITIGATION_SELECTED', 'ESCALATED', 'BACKORDER_ACCEPTED')),
    to_status TEXT NOT NULL CHECK (to_status IN ('OPEN', 'MITIGATION_PROPOSED', 'MITIGATION_SELECTED', 'ESCALATED', 'BACKORDER_ACCEPTED')),
    event_ts TEXT NOT NULL,
    actor_role TEXT NOT NULL CHECK (actor_role IN ('PLANNER', 'OPERATIONS_MANAGER')),
    reason_code TEXT NOT NULL CHECK (reason_code IN ('PAB_BELOW_SAFETY_STOCK', 'OPTIONS_GENERATED', 'BEST_COMPLIANT_OPTION', 'APPROVAL_REQUIRED', 'NO_FEASIBLE_OPTION')),
    mitigation_id TEXT,
    PRIMARY KEY (event_id),
    UNIQUE (shortage_id, seq),
    FOREIGN KEY (shortage_id) REFERENCES shortage (shortage_id),
    FOREIGN KEY (mitigation_id) REFERENCES mitigation_option (mitigation_id)
);

-- Labels for injected anomalies and boundary cases. Never an input to the planner.
CREATE TABLE ground_truth (
    gt_id TEXT NOT NULL,
    case_class TEXT NOT NULL CHECK (case_class IN ('ANOMALY', 'BOUNDARY')),
    issue_type TEXT NOT NULL CHECK (issue_type IN ('DUPLICATE_INBOUND', 'UNAPPROVED_SUBSTITUTE', 'SUPPLIER_CAPACITY_EXCEEDED', 'LEAD_TIME_IGNORED', 'UOM_MISMATCH', 'PO_QTY_EQUALS_MOQ', 'SUPPLIER_LOAD_EQUALS_CAPACITY', 'RECEIPT_EQUALS_LEAD_TIME')),
    entity TEXT NOT NULL,
    record_id TEXT NOT NULL,
    related_record_ids TEXT,
    injection_rule TEXT NOT NULL,
    expected_detection_rule TEXT NOT NULL,
    expected_action TEXT NOT NULL,
    expected_outcome TEXT NOT NULL,
    PRIMARY KEY (gt_id)
);
